package io.github.diodeme.ji.resource.local;

import io.github.diodeme.ji.error.ErrorCode;
import io.github.diodeme.ji.error.JiError;
import io.github.diodeme.ji.error.JiException;
import io.github.diodeme.ji.extension.ProjectTrustStore;
import java.util.Map;
import java.util.Optional;
import java.util.OptionalLong;
import java.util.concurrent.ConcurrentHashMap;

/** In-memory trust adapter used by embedded runtimes and conformance tests. */
public final class MemoryProjectTrustStore implements ProjectTrustStore {
    private final Map<ProjectIdentity, TrustDecision> decisions = new ConcurrentHashMap<>();

    @Override
    public Optional<TrustDecision> find(ProjectIdentity project) {
        return Optional.ofNullable(decisions.get(project));
    }

    @Override
    public synchronized TrustDecision decide(TrustCommand command) {
        TrustDecision current = decisions.get(command.project());
        long currentRevision = current == null ? 0 : current.revision();
        if (command.expectedRevision() != currentRevision) {
            throw new JiException(new JiError(ErrorCode.RESOURCE_TRUST_REVISION_CONFLICT,
                    Map.of("projectId", command.project().value(),
                            "expectedRevision", Long.toString(command.expectedRevision()),
                            "currentRevision", Long.toString(currentRevision)),
                    Optional.empty(), Optional.empty(), OptionalLong.of(currentRevision)));
        }
        TrustDecision next = new TrustDecision(command.project(), command.fingerprint(), command.decision(),
                currentRevision + 1, command.decidedAt());
        decisions.put(command.project(), next);
        return next;
    }
}
